typedef CGAL::Triangulation_vertex_base_2<K> Vb;
typedef CGAL::Triangulation_face_base_2<K> Fb;
typedef CGAL::Triangulation_data_structure_2<Vb, Fb> Tds;
typedef CGAL::Delaunay_triangulation_2<K, Tds> Delaunay;
typedef Delaunay::Face_handle Face_handle;
typedef Delaunay::Point CGALPoint;

Delaunay dt;
for (const auto& p : points) {
    dt.insert(CGALPoint(p.x(), p.y()));
}

std::vector<bool> isSolid(dt.number_of_faces(), false);
int solidComponentCount = 0;

for (Delaunay::Finite_faces_iterator fit = dt.finite_faces_begin(); fit != dt.finite_faces_end(); ++fit) {
    Face_handle fh = fit;
    double circumradius = dt.circumradius(fh);
    if (circumradius <= alpha) {
        isSolid[dt.index(fh)] = true;
    }
}

std::vector<bool> visited(dt.number_of_faces(), false);
std::list<Face_handle> queue;

for (Delaunay::Finite_faces_iterator fit = dt.finite_faces_begin(); fit != dt.finite_faces_end(); ++fit) {
    Face_handle fh = fit;
    int idx = dt.index(fh);
    if (isSolid[idx] && !visited[idx]) {
        visited[idx] = true;
        queue.push_back(fh);
        solidComponentCount++;

        while (!queue.empty()) {
            Face_handle current = queue.front();
            queue.pop_front();
            for (int i = 0; i < 3; ++i) {
                Face_handle neighbor = current->neighbor(i);
                int neighborIdx = dt.index(neighbor);
                if (isSolid[neighborIdx] && !visited[neighborIdx]) {
                    visited[neighborIdx] = true;
                    queue.push_back(neighbor);
                }
            }
        }
    }
}

return solidComponentCount;

